"""Build an offline English HTML report with an interactive 512-state explorer."""
from __future__ import annotations

import argparse
import ast
import base64
import csv
import html
import json
from pathlib import Path

ROOT = Path('/mnt/d/pycharm_community_edition_2024_01_04/py_projects/llm_advice')
REPORT = ROOT/'reports/1101_3LLM_Analysis'
MODELS = ['GPT', 'DeepSeek', 'Qwen']


def read_csv(path):
    with path.open(encoding='utf-8-sig', newline='') as handle:
        return list(csv.DictReader(handle))


def build(allow_partial=False):
    rows = read_csv(REPORT/'merged/combined_answers.csv')
    summaries = {r['model']:r for r in read_csv(REPORT/'data/model_summary.csv')}
    audit = json.loads((REPORT/'data/audit.json').read_text())
    states = []
    for key in sorted({r['grid_key'] for r in rows}):
        selected = [r for r in rows if r['grid_key'] == key]
        item = dict(key=key, center=key[4], direct=int(selected[0]['cardinal_c']), diagonal=int(selected[0]['diagonal_c']))
        for model in MODELS:
            answers = sorted((r for r in selected if r['model_label'] == model), key=lambda r:int(r['repetition']))
            assert len(answers) == 5 and [int(r['repetition']) for r in answers] == list(range(1,6))
            item[model] = dict(c=sum(r['recommendation'] == 'C' for r in answers),
                               old=''.join(r['recommendation'] for r in answers if r['batch_label']=='old'),
                               new=''.join(r['recommendation'] for r in answers if r['batch_label']=='new'))
        item['spread'] = max(item[m]['c'] for m in MODELS)-min(item[m]['c'] for m in MODELS)
        item['disagree'] = len({item[m]['c'] >= 3 for m in MODELS}) > 1
        states.append(item)
    assert len(states) == 512 and len(rows) == 7680
    for model in MODELS:
        assert sum(s[model]['c'] for s in states) == int(summaries[model]['C_answers'])
    captions = {}
    plot_script = ROOT/'tools/plot_five_advice.py'
    if plot_script.exists():
        for node in ast.walk(ast.parse(plot_script.read_text())):
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == 'save' and len(node.args) >= 3:
                try:
                    name, note = ast.literal_eval(node.args[1]), ast.literal_eval(node.args[2])
                    captions[name] = note
                except (ValueError, TypeError):
                    pass
    figures = sorted((REPORT/'figures').glob('[0-9][0-9]_*.png'))
    if not allow_partial:
        assert len(figures) == 9, f'Expected all 9 figures; found {len(figures)}'
    gallery = []
    for path in figures:
        note = captions.get(path.stem, 'Axes, group denominators and descriptive statistics are defined in the figure.')
        title = path.stem.split('_',1)[1].replace('_',' ').title()
        encoded = base64.b64encode(path.read_bytes()).decode()
        gallery.append(f'<figure id="figure-{path.stem[:2]}"><h3>Figure {path.stem[:2]} · {html.escape(title)}</h3>'
                       f'<a href="data:image/png;base64,{encoded}" download="{path.name}" aria-label="Download Figure {path.stem[:2]} as PNG">'
                       f'<img loading="lazy" src="data:image/png;base64,{encoded}" alt="Figure {path.stem[:2]}: {html.escape(title)}. {html.escape(note)}"></a>'
                       f'<figcaption>{html.escape(note).replace(chr(10), "<br>")}</figcaption></figure>')
    overview = ''.join(f'<article class="metric {m.lower()}"><h3>{m}</h3><div class="big">{100*float(summaries[m]["p_C"]):.2f}%</div>'
                       f'<p>C recommendations: <strong>{int(summaries[m]["C_answers"]):,} / 2,560</strong></p>'
                       f'<p>Five replies unanimous in <strong>{summaries[m]["unanimous_states"]} / 512 states</strong>'
                       f' ({100*float(summaries[m]["unanimity_fraction"]):.2f}%).</p></article>' for m in MODELS)
    source_rows = ''.join(f'<tr><th scope="row">{html.escape(s["model_label"])} · {s["batch_label"]}</th>'
                          f'<td>{s["n"]}</td><td>{s["max_output_tokens"]:,}</td>'
                          f'<td>{s["C_answers"]:,} / {s["successful_answers"]:,} ({100*s["C_fraction"]:.2f}%)</td>'
                          f'<td>{s["archived_attempts_excluded"]}</td></tr>' for s in audit['sources'])
    page = TEMPLATE.replace('__OVERVIEW__',overview).replace('__GALLERY__','\n'.join(gallery)).replace('__SOURCE_ROWS__',source_rows)
    page = page.replace('__STATE_DATA__',json.dumps(states, separators=(',',':')).replace('</','<\\/'))
    page = page.replace('__FIGURE_COUNT__',str(len(figures)))
    output = REPORT/'Three_LLM_Advice_Explorer.html'
    output.write_text(page, encoding='utf-8')
    (REPORT/'review').mkdir(exist_ok=True)
    (REPORT/'review/explorer_build_validation.json').write_text(json.dumps(dict(
        states_embedded=512, responses_embedded=7680, figures_embedded=len(figures),
        external_assets_required=False, source_model_counts_crosschecked=True,
        original_five_votes_and_batch_partition_preserved=True,
        output_bytes=output.stat().st_size), indent=2)+'\n',encoding='utf-8')
    print(f'Built {output} ({output.stat().st_size:,} bytes, {len(figures)} figures)')


